import multer from "multer";
import { randomBytes } from "node:crypto";
import { atomic, audit } from "./db.js";

// Call only with a source-controlled SQL column expression.
export const staffImageSql = (userColumn) =>
  `(SELECT '/api/users/' || p.user_id || '/image?v=' || p.revision FROM profile_images p WHERE p.user_id=${userColumn})`;

export function imageUrl(db, userId) {
  const row = db
    .prepare("SELECT revision FROM profile_images WHERE user_id=?")
    .get(userId);
  return row ? `/api/profile/image?v=${row.revision}` : null;
}

// Only passive PNG images generated by the client are stored. No SVG or URLs.
function validPng(buffer) {
  if (
    buffer.length < 45 ||
    !buffer
      .subarray(0, 8)
      .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))
  )
    return false;
  if (
    buffer.readUInt32BE(8) !== 13 ||
    buffer.toString("ascii", 12, 16) !== "IHDR"
  )
    return false;
  const width = buffer.readUInt32BE(16),
    height = buffer.readUInt32BE(20);
  if (!width || !height || width > 1024 || height > 1024) return false;
  let offset = 8,
    data = false;
  while (offset + 12 <= buffer.length) {
    const length = buffer.readUInt32BE(offset);
    if (length > buffer.length - offset - 12) return false;
    const type = buffer.toString("ascii", offset + 4, offset + 8);
    if (type === "IDAT" && length) data = true;
    offset += length + 12;
    if (type === "IEND")
      return length === 0 && offset === buffer.length && data;
  }
  return false;
}

export function registerProfileImages(app, db, allow) {
  app.get("/api/users/:id/image", allow(), (req, res) => {
    const row = db
      .prepare("SELECT image FROM profile_images WHERE user_id=?")
      .get(req.params.id);
    res.set("Cache-Control", "private, no-store");
    if (!row)
      return res
        .status(404)
        .json({ error: "No profile photo has been added." });
    res.type("png").send(Buffer.from(row.image));
  });
  const upload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 1024 * 1024, files: 1, fields: 0 },
  }).single("image");
  app.get("/api/profile/image", allow(), (req, res) => {
    const row = db
      .prepare("SELECT image FROM profile_images WHERE user_id=?")
      .get(req.user.id);
    res.set("Cache-Control", "private, no-store");
    if (!row)
      return res
        .status(404)
        .json({ error: "No profile photo has been added." });
    res.type("png").send(Buffer.from(row.image));
  });
  app.put(
    "/api/profile/image",
    allow(),
    (req, res, next) => {
      upload(req, res, (error) => {
        if (error)
          return res.status(400).json({
            error:
              error.code === "LIMIT_FILE_SIZE"
                ? "Profile photos must be no larger than 1 MB after resizing."
                : "Choose one profile photo.",
          });
        next();
      });
    },
    (req, res) => {
      if (
        !req.file ||
        req.file.mimetype !== "image/png" ||
        !validPng(req.file.buffer)
      )
        return res.status(400).json({
          error: "Choose a valid PNG profile photo up to 1024 × 1024 pixels.",
        });
      const revision = randomBytes(16).toString("hex");
      atomic(db, () => {
        db.prepare(
          "INSERT INTO profile_images(user_id,image,revision) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET image=excluded.image,revision=excluded.revision",
        ).run(req.user.id, req.file.buffer, revision);
        audit(db, req.user.id, "user.photo.update", "user", {
          id: req.user.id,
        });
      });
      res.json({ user: { ...req.user, image_url: imageUrl(db, req.user.id) } });
    },
  );
  app.delete("/api/profile/image", allow(), (req, res) => {
    atomic(db, () => {
      db.prepare("DELETE FROM profile_images WHERE user_id=?").run(req.user.id);
      audit(db, req.user.id, "user.photo.remove", "user", { id: req.user.id });
    });
    res.json({ user: { ...req.user, image_url: null } });
  });
}
